content.content:
1	/**
2	 * 企业命运系统 — 动态商业生态变迁引擎
3	 *
4	 * P2#11：玩家投资/就职/竞争过的公司随时间成长、合并、倒闭，
5	 * 形成可观察的商业生态变迁。5家公司各自经历生命周期阶段，
6	 * 受自然漂移、命运事件、玩家行为三重影响。
7	 *
8	 * Phase 1 完善（2026-06-19）：
9	 * ① 零和博弈市场份额 ② 3个新命运事件(IPO/人才流失/专利战) ③ 真实合并系统
10	 * ④ 行业板块传导 ⑤ 季度企业报告
11	 *
12	 * 设计理念（参考《Dwarf Fortress》历史记忆 + 《CK3》关系网络）：
13	 * - 公司不是静态背景板，而是有生命周期的经济实体
14	 * - 玩家的选择和表现切实影响公司命运
15	 * - 命运事件生成新闻，新闻影响投资，投资反馈到公司
16	 */
17	
18	// ====== 行业板块定义（Phase 1#4） ======
19	var INDUSTRY_SECTORS = {
20	  "AI/大模型": {
21	    name: "AI/大模型",
22	    icon: "🧠",
23	    color: "#7c3aed",
24	    contagionMod: 0.6,
25	    description: "人工智能与大模型研发",
26	  },
27	  "短视频/推荐": {
28	    name: "短视频/推荐",
29	    icon: "📱",
30	    color: "#ec4899",
31	    contagionMod: 0.5,
32	    description: "短视频与内容推荐平台",
33	  },
34	  "云计算/企业服务": {
35	    name: "云计算/企业服务",
36	    icon: "☁️",
37	    color: "#06b6d4",
38	    contagionMod: 0.7,
39	    description: "云计算与企业级服务",
40	  },
41	  "手游/出海": {
42	    name: "手游/出海",
43	    icon: "🎮",
44	    color: "#f59e0b",
45	    contagionMod: 0.4,
46	    description: "移动游戏与海外市场",
47	  },
48	  金融科技: {
49	    name: "金融科技",
50	    icon: "💳",
51	    color: "#10b981",
52	    contagionMod: 0.8,
53	    description: "金融科技与支付",
54	  },
55	};
56	
57	// ====== CEO 特质模板（Phase 1#8 预留，已激活） ======
58	// 注意：此变量需在全局作用域，供 company_spawner.js 调用
59	var CEO_TRAITS = [
60	  {
61	    id: "aggressive",
62	    name: "激进型",
63	    icon: "⚔️",
64	    desc: "高风险高回报，增长事件权重+30%，风险事件权重+20%",
65	    fateWeightMod: { growth: 1.3, risk: 1.2 },
66	  },
67	  {
68	    id: "conservative",
69	    name: "保守型",
70	    icon: "🛡️",
71	    desc: "稳健经营，风险事件权重-40%，恢复事件权重+20%",
72	    fateWeightMod: { risk: 0.6, recovery: 1.2 },
73	  },
74	  {
75	    id: "tech_paranoic",
76	    name: "技术偏执",
77	    icon: "🔬",
78	    desc: "产品驱动，产品爆发事件权重+50%，市场份额增长+10%",
79	    fateWeightMod: { product: 1.5, market: 1.1 },
80	  },
81	  {
82	    id: "finance_oriented",
83	    name: "财务导向",
84	    icon: "📊",
85	    desc: "利润优先，丑闻事件权重-30%，资金链事件权重+10%",
86	    fateWeightMod: { scandal: 0.7, cash: 1.1 },
87	  },
88	  {
89	    id: "visionary",
90	    name: "愿景驱动",
91	    icon: "🌟",
92	    desc: "长期主义，衰退期恢复概率+40%，合并事件权重+25%",
93	    fateWeightMod: { recovery: 1.4, merger: 1.25 },
94	  },
95	];
96	
97	// ====== CEO 人格化深化（Phase 2） ======
98	// 5 家公司的 CEO 详细传记与背景故事
99	
100	var CEO_BIOS = {
101	  star_tech: {
102	    name: "林振宇",
103	    age: 38,
104	    background: "清华计算机博士，曾在硅谷大厂工作8年，2018年回国创业。",
105	    personality:
106	      "技术理想主义者，坚信AI能改变世界。性格内敛但执行力极强，对技术细节有近乎偏执的追求。",
107	    story:
108	      "林振宇的创业之路始于一次深夜的顿悟。2017年，他在斯坦福做访问学者时，目睹了AI在医疗影像诊断上的突破，决心回国做“中国版的医疗AI”。回国后他卖掉硅谷的别墅，在科技园租了个80平的办公室，带着3个同学开始了星辰科技的征程。第一年，他们连工资都发不出来，林振宇靠刷信用卡撑过最艰难的时刻。第三年，他们的医疗影像AI产品获得了首轮融资，如今星辰科技已成为国内AI大模型的领军企业。",
109	    quote: "技术没有捷径，只有死磕。",
110	    weakness: "不善管理，常常亲自写代码到凌晨；对商业变现不够敏感",
111	    relationshipWithPlayer:
112	      "如果玩家就职星辰科技且表现优异，林振宇会亲自带教，传授技术心得。",
113	  },
114	  byte_dragon: {
115	    name: "苏晴",
116	    age: 32,
117	    background: "北大中文系毕业，曾在字节跳动做内容运营3年，2020年离职创业。",
118	    personality:
119	      "敏锐的内容嗅觉，擅长捕捉用户情绪。性格外向、社交能力强，是典型的“内容疯子”。",
120	    story:
121	      "苏晴是内容界的“猎手”。在字节跳动期间，她主导的多个爆款视频播放量破10亿，被内部称为“爆款制造机”。2020年疫情爆发，她敏锐地察觉到短视频出海的机会，辞职创办字节龙，专注做东南亚市场的短视频平台。起步时只有5个人，靠给本地商家做短视频代运营养活团队。两年后，字节龙的日活突破5000万，成为东南亚最大的短视频平台之一。苏晴常说：“内容是有生命的，你得懂用户的心。”",
122	    quote: "流量是表象，人心才是本质。",
123	    weakness: "过度追求流量，有时忽视内容质量；对竞争对手过于激进",
124	    relationshipWithPlayer:
125	      "如果玩家在传媒/内容行业工作，苏晴可能会邀请你加入字节龙的内容团队。",
126	  },
127	  cloud_giant: {
128	    name: "陈建国",
129	    age: 52,
130	    background: "中科院计算所硕士，曾在华为工作15年，2015年创立云巨人。",
131	    personality:
132	      "稳健务实的企业家，信奉“慢就是快”。性格沉稳，做事有条不紊，是业界公认的“老派实干家”。",
133	    story:
134	      "陈建国是典型的“技术老兵”。在华为的15年里，他从一名普通工程师做到产品线总经理，亲历了中国通信产业的崛起。2015年，他看到云计算的浪潮，毅然离开华为创办云巨人。起步时，他选择了最“笨”的路——自建数据中心，而不是轻资产的云服务。这个决定当时被同行嘲笑“过时了”，但三年后，当多家云服务商因数据安全问题被监管调查时，云巨人凭借自有的基础设施赢得了大客户信任。如今，云巨人是国内最大的企业级云服务商之一。",
135	    quote: "做企业就像建房子，地基打牢了，楼才能盖高。",
136	    weakness: "过于保守，错失了一些创新机会；对年轻一代的需求理解不足",
137	    relationshipWithPlayer:
138	      "如果玩家在云计算/企业软件行业工作，陈建国可能会欣赏你的务实态度。",
139	  },
140	  game_fun: {
141	    name: "王浩然",
142	    age: 29,
143	    background:
144	      "浙大游戏设计专业，大学期间做过3款独立游戏，2021年创办好玩游戏。",
145	    personality:
146	      "创意爆棚的游戏狂热者，性格活泼、脑洞大开。对游戏有近乎痴迷的热爱，是“为游戏而生”的典型。",
147	    story:
148	      "王浩然是“游戏界的极客”。大学时他做的第一款独立游戏《逃离宿舍》在Steam上获得了10万销量，让他一举成名。毕业后他没有选择去大厂，而是和两个室友在宿舍里创办了好玩游戏。他们的第一款手游《像素大乱斗》凭借独特的像素风格和创新的玩法，在TapTap上获得了9.2的高分。如今，好玩游戏已成为国内知名的独立游戏发行商，代理了超过30款精品独立游戏。王浩然常说：“游戏是第九艺术，我们要让玩家感受到创作的灵魂。”",
149	    quote: "每一款游戏都是一个世界，我们要做的，是建造最有趣的那个。",
150	    weakness: "过度追求创意，有时忽视商业回报；团队管理较为松散",
151	    relationshipWithPlayer:
152	      "如果玩家对游戏行业感兴趣，王浩然会热情地和你聊游戏设计，甚至邀请你参与游戏测试。",
153	  },
154	  safe_fin: {
155	    name: "张敏",
156	    age: 41,
157	    background: "北大光华MBA，曾在支付宝工作10年，2019年创立安信金融科技。",
158	    personality:
159	      "精明的金融从业者，理性冷静，对风险有极高的敏感度。性格严谨，做事一丝不苟。",
160	    story:
161	      "张敏是“金融科技界的守门人”。在支付宝的10年里，她亲历了中国移动支付从0到1的全过程，负责过风控、合规、产品设计等多个核心岗位。2019年，她看到中小金融机构数字化转型的机会，创办安信金融科技，专注做智能风控系统。起步时，她选择了最“难”的路——为银行做定制化的风控方案，而不是标准化的SaaS产品。这个决定让安信科技在头两年收入增长缓慢，但积累了深厚的行业know-how。如今，安信科技已为超过200家金融机构提供了风控服务。",
162	    quote: "金融的本质是风险管理，技术只是工具。",
163	    weakness: "过于谨慎，错失了一些快速增长的机会；对新兴技术接受度较低",
164	    relationshipWithPlayer:
165	      "如果玩家在金融行业工作，张敏可能会给你一些风控方面的专业建议。",
166	  },
167	};
168	
169	// ====== 10 种命运事件模板（Phase 1 新增3个） ======
170	var FATE_EVENTS = [
171	  {
172	    id: "market_erosion",
173	    label: "市场份额被蚕食",
174	    icon: "🦈",
175	    weight: 1.5,
176	    condition: function (st, co) {
177	      return co.trend === "down" && co.marketShare < 15;
178	    },
179	    apply: function (st, cid, co) {
180	      co.health = Math.max(5, co.health - (10 + Random.int(0, 10)));
181	      co.marketShare = Math.max(1, co.marketShare - (2 + Random.int(0, 3)));
182	      co.sentiment = Math.max(5, co.sentiment - (15 + Random.int(0, 10)));
183	      return { stockMul: 0.94, msg: "市场份额持续萎缩，被竞争对手蚕食" };
184	    },
185	  },
186	  {
187	    id: "product_breakout",
188	    label: "新产品爆发",
189	    icon: "🚀",
190	    weight: 1.2,
191	    condition: function (st, co) {
192	      return (
193	        co.productScore > 65 && co.phase !== "decline" && co.phase !== "dying"
194	      );
195	    },
196	    apply: function (st, cid, co) {
197	      co.health = Math.min(100, co.health + (10 + Random.int(0, 10)));
198	      co.marketShare = Math.min(40, co.marketShare + (3 + Random.int(0, 5)));
199	      co.sentiment = Math.min(100, co.sentiment + (20 + Random.int(0, 10)));
200	      if (co.phase === "mature") co.trend = "up";
201	      return { stockMul: 1.12, msg: "新产品引爆市场，订单暴增" };
202	    },
203	  },
204	  {
205	    id: "scandal",
206	    label: "丑闻曝光",
207	    icon: "📰",
208	    weight: 1.0,
209	    condition: function (st, co) {
210	      return co.sentiment < 45 || (co.trend === "down" && co.health < 60);
211	    },
212	    apply: function (st, cid, co) {
213	      co.health = Math.max(5, co.health - (15 + Random.int(0, 10)));
214	      co.sentiment = Math.max(5, co.sentiment - (25 + Random.int(0, 10)));
215	      co.talentScore = Math.max(5, co.talentScore - (10 + Random.int(0, 5)));
216	      return { stockMul: 0.9, msg: "管理层丑闻曝光，引发信任危机" };
217	    },
218	  },
219	  {
220	    id: "merger_acquire",
221	    label: "收购/合并",
222	    icon: "🤝",
223	    weight: 0.5,
224	    condition: function (st, co) {
225	      // 濒死或高市场占有率成熟公司
226	      return (
227	        co.phase === "dying" || (co.phase === "mature" && co.marketShare > 25)
228	      );
229	    },
230	    apply: function (st, cid, co) {
231	      if (co.phase === "dying") {
232	        // 濒死公司被收购——标记为已退出历史舞台
233	        co.ceasedExistence = true;
234	        co.ceasedAt = st.player.day;
235	        co.health = Math.max(1, co.health - 5);
236	        co.marketShare = Math.max(1, Math.floor(co.marketShare * 0.5));
237	        st.flags["_acquired_" + cid] = true;
238	        if (typeof recordCompanyDeath === "function") {
239	          recordCompanyDeath(
240	            cid,
241	            st,
242	            "经营不善，被竞争对手低价收购",
243	            "merger_acquire",
244	          );
245	        }
246	        // Phase 3: 生成倒闭遗产
247	        generateCompanyAftermath(st, cid, co);
248	        return { stockMul: 0.85, msg: "经营不善，被竞争对手低价收购" };
249	      } else {
250	        // 强势公司并购
251	        co.marketShare = Math.min(40, co.marketShare + 8);
252	        co.health = Math.min(100, co.health + 5);
253	        co.sentiment = Math.min(100, co.sentiment + 10);
254	        return { stockMul: 1.08, msg: "宣布收购同业公司，行业格局重塑" };
255	      }
256	    },
257	  },
258	  {
259	    id: "policy_tailwind",
260	    label: "行业政策利好",
261	    icon: "📋",
262	    weight: 0.8,
263	    condition: function (st, co) {
264	      return co.health > 20; // 任何健康的公司都可能受益
265	    },
266	    apply: function (st, cid, co) {
267	      co.health = Math.min(100, co.health + (5 + Random.int(0, 10)));
268	      co.sentiment = Math.min(100, co.sentiment + (15 + Random.int(0, 10)));
269	      co.trend = "up";
270	      return { stockMul: 1.08, msg: "所在行业获重大政策利好，板块集体走强" };
271	    },
272	  },
273	  {
274	    id: "founder_return",
275	    label: "创始人回归",
276	    icon: "👑",
277	    weight: 0.6,
278	    condition: function (st, co) {
279	      return co.phase === "decline" && co.sentiment < 35;
280	    },
281	    apply: function (st, cid, co) {
282	      co.sentiment = Math.min(100, co.sentiment + (10 + Random.int(0, 10)));
283	      co.talentScore = Math.min(100, co.talentScore + (5 + Random.int(0, 10)));
284	      co.health = Math.min(100, co.health + (5 + Random.int(0, 5)));
285	      co.productScore = Math.min(100, co.productScore + 5);
286	      if (co.health > 40) co.trend = "up";
287	      return { stockMul: 1.06, msg: "创始人回归，启动重大战略重组" };
288	    },
289	  },
290	  {
291	    id: "cash_crisis",
292	    label: "资金链断裂",
293	    icon: "💸",
294	    weight: 0.7,
295	    condition: function (st, co) {
296	      return co.phase === "decline" || co.phase === "dying";
297	    },
298	    apply: function (st, cid, co) {
299	      co.health = Math.max(3, co.health - (20 + Random.int(0, 10)));
300	      co.sentiment = Math.max(5, co.sentiment - 20);
301	      co.talentScore = Math.max(5, co.talentScore - (10 + Random.int(0, 10)));
302	      if (co.health < 10 && co.phase !== "dying") co.phase = "dying";
303	      return { stockMul: 0.85, msg: "资金链断裂，大规模裁员自救" };
304	    },
305	  },
306	  {
307	    id: "company_death",
308	    label: "公司倒闭",
309	    icon: "⚰️",
310	    weight: 0.3,
311	    condition: function (st, co) {
312	      return co.phase === "dying" && co.health < 5 && !co.ceasedExistence;
313	    },
314	    apply: function (st, cid, co) {
315	      co.ceasedExistence = true;
316	      co.ceasedAt = st.player.day;
317	      co.health = 0;
318	      // 记录到多周目记忆
319	      if (typeof recordCompanyDeath === "function") {
320	        var cause = "经营彻底失败，宣布破产清算";
321	        if (co.fateEventHistory && co.fateEventHistory.length > 0) {
322	          var last = co.fateEventHistory[co.fateEventHistory.length - 1];
323	          cause = last.description + "，最终无力回天";
324	        }
325	        recordCompanyDeath(cid, st, cause, "company_death");
326	      }
327	      // Phase 3: 生成倒闭遗产
328	      generateCompanyAftermath(st, cid, co);
329	      return { stockMul: 0.5, msg: "正式宣告破产，公司关闭清算" };
330	    },
331	  },
332	  // ===== Phase 1 新增事件 =====
333	  {
334	    id: "ipo_listing",
335	    label: "IPO上市",
336	    icon: "🔔",
337	    weight: 0.4,
338	    condition: function (st, co) {
339	      // 成长期或成熟期，健康度高，市场份额达标
340	      return (
341	        (co.phase === "growth" || co.phase === "mature") &&
342	        co.health > 75 &&
343	        co.marketShare > 12 &&
344	        !co.ceasedExistence &&
345	        !co.ipoed
346	      );
347	    },
348	    apply: function (st, cid, co) {
349	      co.ipoed = true;
350	      co.ipoDay = st.player.day;
351	      // 资本暴涨
352	      co.health = Math.min(100, co.health + 15);
353	      co.sentiment = Math.min(100, co.sentiment + 30);
354	      co.marketShare = Math.min(45, co.marketShare + 5);
355	      co.trend = "up";
356	      // 解锁股票交易（标记为IPO公司）
357	      if (st.flags) st.flags["_ipo_" + cid] = true;
358	      // 生成IPO新闻
359	      var companyName = getCompanyNameById(cid);
360	      var msg =
361	        "成功在港交所/纳斯达克挂牌上市，首日市值突破" +
362	        (100 + Math.floor(Math.random() * 200)) +
363	        Random.int(100, 299) +
364	        "亿";
365	      return { stockMul: 1.25, msg: msg };
366	    },
367	  },
368	  {
369	    id: "talent_exodus",
