753	/**
754	 * 企业命运每日结算 — 由 daily_pipeline 调用
755	 */
756	function tickEnterpriseFate(state) {
757	  if (!state.enterpriseFate || !state.enterpriseFate.companies) return;
758	
759	  var fate = state.enterpriseFate;
760	  var companies = fate.companies;
761	  var hasStocks =
762	    typeof INV_STOCKS !== "undefined" && typeof CORP_STOCK_MAP !== "undefined";
763	  var inv = state.investment;
764	
765	  for (var cid in companies) {
766	    var co = companies[cid];
767	    if (!co) continue;
768	
769	    // 1. 自然漂移
770	    var phaseDef =
771	      CORP_LIFECYCLE_PHASES[co.phase] || CORP_LIFECYCLE_PHASES.mature;
772	
773	    // health: 缓慢向中间值收敛
774	    var healthDrift = Random.float(-1, 1) * (phaseDef.recoveryRate || 0.1);
775	    co.health = Math.max(1, Math.min(100, co.health + healthDrift));
776	
777	    // marketShare: 受阶段影响
778	    var shareDrift =
779	      Random.float(-0.3, 0.3) +
780	      (co.trend === "up" ? 0.15 : co.trend === "down" ? -0.15 : 0);
781	    co.marketShare = Math.max(1, Math.min(45, co.marketShare + shareDrift));
782	
783	    // sentiment: 随机波动
784	    co.sentiment = Math.max(
785	      5,
786	      Math.min(100, co.sentiment + (Math.random() - 0.5) * 4),
787	    );
788	
789	    // 2. 阶段转换
790	    if (co.health < 20 && co.phase !== "dying") {
791	      co.phase = "dying";
792	      co.trend = "down";
793	    } else if (co.health < 45 && co.phase === "growth") {
794	      co.phase = "decline";
795	      co.trend = "down";
796	    } else if (co.health > 65 && co.phase === "decline") {
797	      co.phase = "mature";
798	      co.trend = "stable";
799	    } else if (co.health > 80 && co.phase === "startup") {
800	      co.phase = "growth";
801	      co.trend = "up";
802	    }
803	
804	    // 更新trend
805	    if (co.trend === "stable" && co.health > 70) co.trend = "up";
806	    if (co.trend === "up" && co.health < 30) co.trend = "down";
807	    if (co.trend === "down" && co.health > 75) co.trend = "up";
808	
809	    // 3.5 倒闭检测：濒死且健康度极低 → 公司倒闭
810	    if (co.phase === "dying" && co.health < 3 && !co.ceasedExistence) {
811	      co.ceasedExistence = true;
812	      co.ceasedAt = state.player.day;
813	      co.health = 0;
814	      var name = getCompanyNameById(cid);
815	      if (typeof recordCompanyDeath === "function") {
816	        recordCompanyDeath(
817	          cid,
818	          state,
819	          "健康度耗尽，在挣扎中彻底倒下",
820	          "natural_death",
821	        );
822	      }
823	      // Phase 3: 生成倒闭遗产
824	      generateCompanyAftermath(state, cid, co);
825	      if (typeof StateManager !== "undefined") {
826	        StateManager.addMessage(
827	          "⚰️ 【" + name + "】正式倒闭，退出市场舞台",
828	          "danger",
829	        );
830	      }
831	    }
832	    if (!co.knownToPlayer) {
833	      if (state.corporate && state.corporate.company === cid) {
834	        co.knownToPlayer = true;
835	      }
836	      if (hasStocks && inv && inv.stockHoldings) {
837	        var stockSymbols = CORP_STOCK_MAP[cid] || [];
838	        for (var si = 0; si < inv.stockHoldings.length; si++) {
839	          if (stockSymbols.indexOf(inv.stockHoldings[si].symbol) >= 0) {
840	            co.knownToPlayer = true;
841	            break;
842	          }
843	        }
844	      }
845	    }
846	  }
847	
848	  // 4. 股票价格牵引（温和拉向公司健康度方向）
849	  if (hasStocks && inv && inv.stockMarket) {
850	    for (var cid2 in CORP_STOCK_MAP) {
851	      var co2 = companies[cid2];
852	      if (!co2) continue;
853	      var symbols = CORP_STOCK_MAP[cid2];
854	      for (var si2 = 0; si2 < symbols.length; si2++) {
855	        var mkt = inv.stockMarket[symbols[si2]];
856	        if (!mkt) continue;
857	        // 计算目标乘数: health + sentiment + marketShare 综合
858	        var targetMul =
859	          0.7 +
860	          (co2.health / 100) * 0.15 +
861	          (co2.sentiment / 100) * 0.1 +
862	          (co2.marketShare / 30) * 0.05;
863	        // 温和牵引: 每次向目标移动0.5%
864	        mkt.price = mkt.price * (1 - 0.005) + mkt.price * targetMul * 0.005;
865	        mkt.price = Math.max(0.0001, Math.round(mkt.price * 10000) / 10000);
866	      }
867	    }
868	  }
869	
870	  // 5. 风声 pending events 到期触发
871	  tickPendingEvents(state);
872	
873	  // 6. 命运事件触发（生成风声，延迟3-5天实际生效）
874	  rollFateEvent(state);
