876	  // 7. Phase 3: 半年新公司生成检查（从废墟中重生）
877	  if (typeof checkAndSpawnFromRuins === "function") {
878	    checkAndSpawnFromRuins(state);
879	  }
880	
881	  fate.lastFateTick = state.player.day;
882	}
