1160	function applyZeroSumMarketShare(state, growingCid, growingAmount) {
1161	  var fate = state.enterpriseFate;
1162	  if (!fate || !fate.companies) return;
1163	
1164	  var companies = fate.companies;
1165	  var totalShare = 0;
1166	  var shareMap = {};
1167	
1168	  // 计算当前总市场份额
1169	  for (var cid in companies) {
1170	    var co = companies[cid];
1171	    if (!co || co.ceasedExistence) continue;
1172	    shareMap[cid] = co.marketShare || 0;
1173	    totalShare += shareMap[cid];
1174	  }
1175	
1176	  if (totalShare <= 0) return;
1177	
1178	  // 如果总份额超过上限（约80%），按比例从非增长公司抽取
1179	  var MAX_TOTAL_SHARE = 80;
1180	  if (totalShare + growingAmount > MAX_TOTAL_SHARE) {
1181	    var excess = totalShare + growingAmount - MAX_TOTAL_SHARE;
1182	
1183	    // 找出非增长公司，按市场份额比例分配损失
1184	    var candidates = [];
1185	    var candidateTotal = 0;
1186	    for (var cId2 in shareMap) {
1187	      if (cId2 === growingCid && growingAmount > 0) continue;
1188	      if (shareMap[cId2] > 1) {
1189	        candidates.push({ cid: cId2, share: shareMap[cId2] });
1190	        candidateTotal += shareMap[cId2];
1191	      }
1192	    }
1193	
1194	    if (candidates.length > 0) {
1195	      for (var ci = 0; ci < candidates.length; ci++) {
1196	        var c = candidates[ci];
1197	        var loss = (excess * c.share) / candidateTotal;
1198	        companies[c.cid].marketShare = Math.max(
1199	          1,
1200	          (companies[c.cid].marketShare || 0) - loss,
1201	        );
1202	      }
1203	    }
1204	  }
1205	
1206	  // 应用增长
1207	  if (growingCid && companies[growingCid]) {
1208	    companies[growingCid].marketShare = Math.min(
1209	      45,
1210	      (companies[growingCid].marketShare || 0) + growingAmount,
1211	    );
1212	  }
1213	}
