1624	  var confidenceGain = 0;
1625	  if (channel === "work") confidenceGain = 8 + Math.random() * 12;
1626	  else if (channel === "social") confidenceGain = 10 + Math.random() * 15;
1627	  else if (channel === "npc") confidenceGain = 8 + Math.random() * 12;
1628	  else if (channel === "news") confidenceGain = 4 + Math.random() * 8;
