1872	      continue; // 未实际发生或已处理
1873	
1874	    // 检查交易窗口：风声期到事件发生
1875	    var tradeWindowStart = rumor.detectedDay;
1876	    var tradeWindowEnd = rumor.resolvedDay;
1877	
1878	    // 找出相关交易
1879	    var suspiciousTrades = [];
1880	    for (var ti = 0; ti < state.insiderTrading.tradeLog.length; ti++) {
1881	      var trade = state.insiderTrading.tradeLog[ti];
1882	      if (trade.day >= tradeWindowStart && trade.day <= tradeWindowEnd) {
